arguments.query:
CREATE TABLE IF NOT EXISTS todos (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  status TEXT DEFAULT 'pending',
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS todo_deps (
  todo_id TEXT,
  depends_on TEXT,
  PRIMARY KEY (todo_id, depends_on)
);
INSERT OR REPLACE INTO todos (id, title, description, status) VALUES
  ('render-contact-page', 'Render standalone contact page', 'Create a single HTML document with a React-style component structure, semantic landmarks, and the support contact form UI.', 'pending'),
  ('implement-validation', 'Implement form validation', 'Add client-side validation for required full name and email fields, optional phone handling, and inline error messaging tied to each control.', 'pending'),
  ('style-page', 'Style the page', 'Apply modern product-style layout, typography, spacing, and accessible focus states while keeping the page responsive.', 'pending'),
  ('verify-accessibility', 'Verify accessible behavior', 'Check the final HTML artifact in a browser-based accessibility pass and correct any issues found.', 'pending');
INSERT OR REPLACE INTO todo_deps (todo_id, depends_on) VALUES
  ('implement-validation', 'render-contact-page'),
  ('style-page', 'render-contact-page'),
  ('verify-accessibility', 'render-contact-page'),
  ('verify-accessibility', 'implement-validation'),
  ('verify-accessibility', 'style-page');
UPDATE todos SET status = 'in_progress', updated_at = CURRENT_TIMESTAMP WHERE id = 'render-contact-page';
SELECT id, title, status FROM todos ORDER BY created_at;

