+                <ul class="support-list">
+                  <li>
+                    <strong>Fast triage</strong>
+                    We confirm the details and route the request to the best-fit team.
+                  </li>
+                  <li>
+                    <strong>Clear updates</strong>
+                    You’ll get a response with the information we need or the fix we recommend.
+                  </li>
+                </ul>
+              </aside>
+            </div>
+          </main>
+        `;
+      }
+
+      document.getElementById("app").innerHTML = supportPage();
+
+      const form = document.getElementById("support-form");
+      const status = document.getElementById("form-status");
+      const controls = Array.from(form.querySelectorAll(".field-input"));
+
+      let submitted = false;
+
+      function validateFullName(value) {
+        return value.trim() ? "" : "Error: Enter your full name.";
+      }
+
+      function validateEmail(value) {
+        const trimmed = value.trim();
+        if (!trimmed) {
+          return "Error: Enter your email address.";
+        }
+
+        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
+          ? ""
+          : "Error: Enter a valid email address like name@example.com.";
+      }
+
+      function validatePhone(value) {
+        const trimmed = value.trim();
+        if (!trimmed) {
+          return "";
+        }
+
+        const allowedCharacters = /^[+\d().\s-]+$/;
+        const digits = trimmed.replace(/\D/g, "");
+
+        return allowedCharacters.test(trimmed) && digits.length >= 7 && digits.length <= 15
+          ? ""
+          : "Error: Enter a valid phone number like +1 555 123 4567 or (555) 123-4567.";
+      }
+
+      function validatorFor(name) {
+        switch (name) {
+          case "fullName":
+            return validateFullName;
+          case "email":
+            return validateEmail;
+          case "phone":
+            return validatePhone;
+          default:
+            return () => "";
+        }
+      }
+
+      function setFieldState(input, message) {
+        const errorElement = document.getElementById(input.dataset.errorId);
+        const hasError = Boolean(message);
+
+        input.setAttribute("aria-invalid", hasError ? "true" : "false");
+        errorElement.textContent = message;
+        errorElement.hidden = !hasError;
+      }
+
+      function validateField(input, forceDisplay = false) {
+        const message = validatorFor(input.name)(input.value);
+        const touched = input.dataset.touched === "true";
+        const shouldShow = forceDisplay || touched || submitted;
+
+        if (message && shouldShow) {
+          setFieldState(input, message);
+        } else {
+          setFieldState(input, "");
+        }
+
+        return !message;
+      }
+
+      controls.forEach((input) => {
+        input.addEventListener("blur", () => {
+          input.dataset.touched = "true";
+          validateField(input, true);
+        });
+
+        input.addEventListener("input", () => {
+          if (input.dataset.touched === "true" || submitted) {
+            validateField(input, true);
+          }
+        });
+      });
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        submitted = true;
+
+        const firstInvalid = controls.find((input) => !validateField(input, true));
+
+        if (firstInvalid) {
+          status.hidden = false;
+          status.className = "status status--error";
+          status.textContent = "Please correct the highlighted fields.";
+          firstInvalid.focus();
+          return;
+        }
+
+        status.hidden = false;
+        status.className = "status status--success";
+        status.textContent = "Thanks — your message is ready to send.";
+        form.reset();
+
+        controls.forEach((input) => {
+          input.dataset.touched = "false";
+          setFieldState(input, "");
+        });
+
+        submitted = false;
+      });
+    </script>
+  </body>
+</html>
*** End Patch
', intention_summary=None, mcp_server_name=None, tool_title=None, type=<AssistantMessageToolRequestType.CUSTOM: 'custom'>)

