        phone: {
          id: "phone-number",
          label: "Phone number",
          name: "phone",
          type: "tel",
          autocomplete: "tel",
          inputmode: "tel",
          required: false,
          placeholder: "+1 555 123 4567"
        }
      };

      function requiredMark() {
        return '<span class="required-mark" aria-hidden="true">*</span>';
      }

