            ${helpText ? `<p class="field-help" id="${id}-help">${helpText}</p>` : ""}
            <p class="field-error" id="${id}-error" role="alert" hidden>${errorText}</p>
          </div>
        `;
      }

      function supportPage() {
        return `
          <header class="page-shell">
            <div class="hero">
              <p class="eyebrow">Support</p>
              <h1>Contact our team</h1>
              <p class="lead">
                Send a message and we’ll route it to the right support specialist. Required fields are marked with an asterisk.
              </p>
            </div>
          </header>

          <main id="main" class="page-shell" tabindex="-1">
            <div class="layout">
              <section class="card form-card" aria-labelledby="contact-form-title">
                <h2 id="contact-form-title">Contact form</h2>
                <form id="support-form" novalidate>
                  ${formField({
                    ...fieldDescriptors.fullName,
                    errorText: "Error: Enter your full name."
                  })}

                  ${formField({
                    ...fieldDescriptors.email,
                    errorText: "Error: Enter a valid email address like name@example.com."
                  })}

                  ${formField({
                    ...fieldDescriptors.phone,
                    helpText: "Optional. Use a format like +1 555 123 4567 or (555) 123-4567.",
                    errorText: "Error: Enter a valid phone number like +1 555 123 4567 or (555) 123-4567."
                  })}

                  <div class="actions">
                    <button class="submit-button" type="submit">Send message</button>
                    <p class="status" id="form-status" aria-live="polite" hidden></p>
                  </div>
                </form>
              </section>

              <aside class="card aside-card" aria-labelledby="support-details-title">
                <h2 id="support-details-title">What happens next</h2>
                <p>We review every request in the order it arrives and reply with the next step as soon as possible.</p>
                <ul class="support-list">
                  <li>
                    <strong>Fast triage</strong>
                    We confirm the details and route the request to the best-fit team.
                  </li>
                  <li>
                    <strong>Clear updates</strong>
                    You’ll get a response with the information we need or the fix we recommend.
                  </li>
                </ul>
              </aside>
            </div>
          </main>
        `;
      }

      document.getElementById("app").innerHTML = supportPage();

      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");
      const controls = Array.from(form.querySelectorAll(".field-input"));

      let submitted = false;

      function validateFullName(value) {
        return value.trim() ? "" : "Error: Enter your full name.";
      }

      function validateEmail(value) {
        const trimmed = value.trim();
        if (!trimmed) {
          return "Error: Enter your email address.";
        }

        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
          ? ""
          : "Error: Enter a valid email address like name@example.com.";
      }

      function validatePhone(value) {
