        if (!trimmed) {
          return "";
        }

        const allowedCharacters = /^[+\d().\s-]+$/;
        const digits = trimmed.replace(/\D/g, "");

        return allowedCharacters.test(trimmed) && digits.length >= 7 && digits.length <= 15
          ? ""
          : "Error: Enter a valid phone number like +1 555 123 4567 or (555) 123-4567.";
      }

      function validatorFor(name) {
        switch (name) {
          case "fullName":
            return validateFullName;
          case "email":
            return validateEmail;
          case "phone":
            return validatePhone;
          default:
            return () => "";
        }
      }

      function setFieldState(input, message) {
        const errorElement = document.getElementById(input.dataset.errorId);
        const hasError = Boolean(message);

        input.setAttribute("aria-invalid", hasError ? "true" : "false");
        errorElement.textContent = message;
        errorElement.hidden = !hasError;
      }

      function validateField(input, forceDisplay = false) {
        const message = validatorFor(input.name)(input.value);
        const touched = input.dataset.touched === "true";
        const shouldShow = forceDisplay || touched || submitted;

        if (message && shouldShow) {
          setFieldState(input, message);
        } else {
          setFieldState(input, "");
        }

        return !message;
      }

      controls.forEach((input) => {
        input.addEventListener("blur", () => {
          input.dataset.touched = "true";
          validateField(input, true);
        });

        input.addEventListener("input", () => {
          if (input.dataset.touched === "true" || submitted) {
            validateField(input, true);
          }
        });
