     <a class="skip-link" href="#main">Skip to main content</a>
     <div id="app"></div>

     <script>
       const fieldDescriptors = {
         fullName: {
           id: "full-name",
           label: "Full name",
           name: "fullName",
           type: "text",
           autocomplete: "name",
           required: true,
           placeholder: "Jordan Lee"
         },
         email: {
           id: "email-address",
           label: "Email address",
           name: "email",
           type: "email",
           autocomplete: "email",
           required: true,
           placeholder: "name@example.com"
         },
         phone: {
           id: "phone-number",
           label: "Phone number",
           name: "phone",
           type: "tel",
           autocomplete: "tel",
           inputmode: "tel",
           required: false,
           placeholder: "+1 555 123 4567"
         }
       };

       function requiredMark() {
         return '<span class="required-mark" aria-hidden="true">*</span>';
       }

       function formField({ id, label, name, type, autocomplete, inputmode, required, placeholder, helpText, errorText }) {
         const describedBy = [helpText && `${id}-help`, `${id}-error`].filter(Boolean).join(" ");
         return `
           <div class="form-field">
             <label for="${id}">${label}${required ? requiredMark() : ""}</label>
             <input
               class="field-input"
               id="${id}"
               name="${name}"
               type="${type}"
               autocomplete="${autocomplete}"
               ${inputmode ? `inputmode="${inputmode}"` : ""}
               ${required ? "required" : ""}
               placeholder="${placeholder}"
               aria-describedby="${describedBy}"
               aria-invalid="false"
               data-error-id="${id}-error"
             />
             ${helpText ? `<p class="field-help" id="${id}-help">${helpText}</p>` : ""}
             <p class="field-error" id="${id}-error" role="alert" hidden>${errorText}</p>
           </div>
         `;
       }

       function supportPage() {
         return `
           <header class="page-shell">
             <div class="hero">
               <p class="eyebrow">Support</p>
               <h1>Contact our team</h1>
               <p class="lead">
                 Send a message and we’ll route it to the right support specialist. Required fields are marked with an asterisk.
               </p>
             </div>
           </header>

           <main id="main" class="page-shell" tabindex="-1">
             <div class="layout">
               <section class="card form-card" aria-labelledby="contact-form-title">
                 <h2 id="contact-form-title">Contact form</h2>
                 <form id="support-form" novalidate>
                   ${formField({
                     ...fieldDescriptors.fullName,
                     errorText: "Error: Enter your full name."
                   })}

                   ${formField({
                     ...fieldDescriptors.email,
                     errorText: "Error: Enter a valid email address like name@example.com."
                   })}

                   ${formField({
                     ...fieldDescriptors.phone,
                     helpText: "Optional. Use a format like +1 555 123 4567 or (555) 123-4567.",
                     errorText: "Error: Enter a valid phone number like +1 555 123 4567 or (555) 123-4567."
                   })}

                   <div class="actions">
                     <button class="submit-button" type="submit">Send message</button>
                     <p class="status" id="form-status" aria-live="polite" hidden></p>
                   </div>
                 </form>
               </section>

               <aside class="card aside-card" aria-labelledby="support-details-title">
                 <h2 id="support-details-title">What happens next</h2>
                 <p>We review every request in the order it arrives and reply with the next step as soon as possible.</p>
                 <ul class="support-list">
                   <li>
                     <strong>Fast triage</strong>
                     We confirm the details and route the request to the best-fit team.
                   </li>
                   <li>
                     <strong>Clear updates</strong>
                     You’ll get a response with the information we need or the fix we recommend.
                   </li>
                 </ul>
               </aside>
             </div>
           </main>
         `;
       }

       document.getElementById("app").innerHTML = supportPage();

       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");
       const controls = Array.from(form.querySelectorAll(".field-input"));

       let submitted = false;

       function validateFullName(value) {
         return value.trim() ? "" : "Error: Enter your full name.";
       }

       function validateEmail(value) {
         const trimmed = value.trim();
         if (!trimmed) {
           return "Error: Enter your email address.";
         }

         return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
           ? ""
           : "Error: Enter a valid email address like name@example.com.";
       }

       function validatePhone(value) {
         const trimmed = value.trim();
         if (!trimmed) {
           return "";
         }

         const allowedCharacters = /^[+\d().\s-]+$/;
         const digits = trimmed.replace(/\D/g, "");

         return allowedCharacters.test(trimmed) && digits.length >= 7 && digits.length <= 15
           ? ""
           : "Error: Enter a valid phone number like +1 555 123 4567 or (555) 123-4567.";
       }

       function validatorFor(name) {
         switch (name) {
           case "fullName":
             return validateFullName;
           case "email":
             return validateEmail;
           case "phone":
             return validatePhone;
           default:
             return () => "";
         }
       }

       function setFieldState(input, message) {
         const errorElement = document.getElementById(input.dataset.errorId);
         const hasError = Boolean(message);

         input.setAttribute("aria-invalid", hasError ? "true" : "false");
         errorElement.textContent = message;
         errorElement.hidden = !hasError;
       }

       function validateField(input, forceDisplay = false) {
         const message = validatorFor(input.name)(input.value);
         const touched = input.dataset.touched === "true";
         const shouldShow = forceDisplay || touched || submitted;

         if (message && shouldShow) {
           setFieldState(input, message);
         } else {
           setFieldState(input, "");
         }

         return !message;
       }

       controls.forEach((input) => {
         input.addEventListener("blur", () => {
           input.dataset.touched = "true";
           validateField(input, true);
         });

         input.addEventListener("input", () => {
           if (input.dataset.touched === "true" || submitted) {
             validateField(input, true);
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         submitted = true;

         const invalidControls = [];

         controls.forEach((input) => {
           if (!validateField(input, true)) {
             invalidControls.push(input);
           }
         });

         if (invalidControls.length) {
           status.hidden = false;
           status.className = "status status--error";
           status.textContent = "Please correct the highlighted fields.";
           invalidControls[0].focus();
           return;
         }

         status.hidden = false;
         status.className = "status status--success";
         status.textContent = "Thanks — your message is ready to send.";
         form.reset();

         controls.forEach((input) => {
           input.dataset.touched = "false";
           setFieldState(input, "");
         });

         submitted = false;
       });
     </script>
   </body>
 </html>

